examples.template:
CompositionLocalProvider(LocalConfiguration provides locale) {
    MonarchGauge(
        value = {{value|double}},
        bands = listOf(
            MonarchGaugeBand({{bands.0.from|double}}..{{bands.0.to|double}}, {{bands.0.tone|tone}}, {{bands.0.label}}),
            MonarchGaugeBand({{bands.1.from|double}}..{{bands.1.to|double}}, {{bands.1.tone|tone}}, {{bands.1.label}}),
            MonarchGaugeBand({{bands.2.from|double}}..{{bands.2.to|double}}, {{bands.2.tone|tone}}, {{bands.2.label}}),
        ),
        label = {{label}},
        description = {{description}},
        formatValue = { "${it.roundToInt()}%" },
    )
}

examples.setupTemplate:
val configuration = LocalConfiguration.current
val locale = remember(configuration) {
    Configuration(configuration).apply { setLocale(Locale.forLanguageTag({{locale}})) }
}

examples.setup:
val configuration = LocalConfiguration.current
val locale = remember(configuration) {
    Configuration(configuration).apply { setLocale(Locale.forLanguageTag("en-US")) }
}

examples.code:
CompositionLocalProvider(LocalConfiguration provides locale) {
    MonarchGauge(
        value = 76.0,
        bands = listOf(
            MonarchGaugeBand(0.0..70.0, MonarchTone.Success, "Healthy"),
            MonarchGaugeBand(70.0..90.0, MonarchTone.Warning, "High"),
            MonarchGaugeBand(90.0..100.0, MonarchTone.Danger, "Critical"),
        ),
        label = "CPU load",
        description = "Average over 5 minutes",
        formatValue = { "${it.roundToInt()}%" },
    )
}
